
import React, { useState, useEffect } from "react";



import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import {  TextInput_Cmpt,  CheckBox_Cmpt } from "../../../components";
import { updStore, getStore, gen16CodeId, ObjectKeys, fetchEncryptStream, _monthNames, qryStore, isValidFunction } from "../../../stores/Utils";

import { GrayButton } from "../../../components/Buttons";

import {  getall_categories, getFNMLabels } from "../services/customer_fetch_service";



const TextInput = TextInput_Cmpt();



const CheckBox = CheckBox_Cmpt();












