const Categories2Filter  = ({ data,  confirm, type, init }) => {
	
	


	const [initialize, setInitialize] = useState(false);

	const [, set_obs] = useState(1);
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	const getallCategoriesMobile =  () => {
		getall_categories(updObs);
	}
	
	useEffect(() => {
		if (!initialize) {
			
			setInitialize(true);
			set_obs(gen16CodeId());
			getallCategoriesMobile()
		}
	});


	const updCategoryFilter = ( v) => {
		set_obs(gen16CodeId());
			if(isValidFunction(confirm)){
				close();
				confirm(v);
			}
		
	};



	


	const addView =  (v) => {
		
		let dataMdl = {};
		dataMdl["zIndex"] = 480;
		// data['observeResize']=true;
		dataMdl["props"] = { minHeight: "1vh", overlay: true };
		dataMdl["content"] = <AddCategory  />
		OpenModal(dataMdl);
	}


	const close  = ()  => {
		data?.modalID && CloseModal({id:data?.modalID});
	}

	let data2Render = getStore("categories_list");

	return(
		<div style={{
			height: "80vh",
			width: "90vw",
			overflow: "auto",
			background: "var(--dark-800)",
			borderRadius: 13,
			padding: "20px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title blue30" style={{margin: "10px"}}>
					
					{getFNMLabels(54)}
				</p>
				<div className="flexSpace"/>

				<div className="">
					<GrayButton color={"#007bfc"} label={getFNMLabels(46)} clickHandler={addView}/>
				</div>
			
			</div>
			
			
			
			<div className=" spaceAround flxWrp scollVh" style={{marginTop:20, maxHeight: "calc( 78vh - 70px)"}}>
				
				{data2Render && ObjectKeys(data2Render)?.map(cid=>{
					return (
						<BtnCategory
							data={data2Render[cid]}
							elmId={data2Render[cid].categoryId} 
							label={data2Render[cid].name} 
							clickHandler={updCategoryFilter}
							active={init}
							key={data2Render[cid].categoryId}
							type={type}
						/>
					)
				})}
			</div>
		
			
		</div>
	)

}



export default Categories2Filter;








const BtnCategory  = ({ clickHandler, label, active,  elmId, data, type}) => {
	let nexV = active === elmId?null:elmId;
	if(data.type !== type){
		return null;
	}
	return (
		<div className={` btn_filter itmMrg ${active === elmId?"active":""} `} onClick={()=>clickHandler(nexV)} >
			{label}
		</div>
	)
}










const AddCategory  = ({ data,  confirm, type, init }) => {
	
	

	const frmNm = "add_category_frm"

	
	const [obs, set_obs] = useState(1);
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}


	const save  = async ()  => {
		
		let ffm = getStore(frmNm);

		ffm.categoryId = gen16CodeId();
		
		let bdyq2 = {...getStore(qryStore())?.add_categapp};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId
		}
		bdyq2.form=ffm;

		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			updStore(frmNm, {});
			confirm && confirm();
			close();
		}
		
	};

	const close  = ()  => {
		data?.modalID && CloseModal({id:data?.modalID});
	}

	

	const updFrm = (f, v) => {
		let frm2 = getStore(frmNm) || {};
		frm2[f] = v;
		updStore(frmNm, frm2);
		set_obs(gen16CodeId())
	};



	return(
		<div style={{
			height: "80vh",
			width: "90vw",
			overflow: "auto",
			background: "var(--dark-800)",
			borderRadius: 13,
			padding: "20px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title blue30" style={{margin: "10px"}}>
					{getFNMLabels(46)}	{getFNMLabels(54)}
				</p>
				<div className="flexSpace"/>

				<div className="">
					<GrayButton color={"#007bfc"} label={getFNMLabels(43)} clickHandler={save}/>
				</div>
			
			</div>
			
			
			
			<div className="" style={{margin: "30px 0"}}>
				<div className="lbl_dtls">
					<TextInput  
						init={getStore(frmNm)?.name}
						width={"68vw"}
						label={getFNMLabels(56)}
						updChanges={(e)=>updFrm("name",e)}
					/>	
				</div>
				<div className="lbl_dtls">
					<TextInput  
						init={getStore(frmNm)?.description}
						width={"68vw"}
						label={getFNMLabels(53)}
						updChanges={(e)=>updFrm("description",e)}
					/>	
				</div>
				<div className="_dsplFlx " style={{padding: "48px 10px 10px"}}>
					<div className="flexSpace"/>
					<CheckBox 
						data={[
							{label: getFNMLabels(40) , id:"expenses"},
							{label: getFNMLabels(42) , id:"incomes"}
						]}
						active={getStore(frmNm)?.["type"]}
						updSelect={(e)=>updFrm("type",e)}
						colors={{
							"--base-ck-primary-color":"var(--primary-blue--backg-30)",
							"--base-ck-primary-backcolor":"var(--primary-blue--color-30)",
						}}
					/>
				</div>

				
			</div>
		
			
		</div>
	)

}
