import { useState, useRef, forwardRef, useImperativeHandle  } from "react";

 
const ComponentRender = forwardRef(({ initValue }, ref) => {
  const [value,setValue] = useState(initValue)
  useImperativeHandle(ref, () => ({
		refresh(v) {
			setValue(v);
		}
  }));
  return 	<> {value}</>
})

const ReferenceRender = "referenceRender"



export const useObject = (initValue, updateType) => {

  const [,dispatch] = useState(initValue)
  const shallowRef = useRef(null);
  const obj = useRef(new Proxy({value:initValue}, {
    get: function(obj, prop) {
      if(updateType.shallowRender && prop === ReferenceRender){
        return <ComponentRender 
          initValue={obj.value} 
          ref={shallowRef} 
        />
      }
      else if (obj[prop]) {
        return obj[prop];
      }
      return Reflect.get(...arguments)
    },
    set: function(obj, prop, value) {
      if (obj[prop] !== value) {
        obj[prop] = value;
        if(updateType.shallowRender){
          shallowRef?.current?.refresh(value);
        }
        else{
          dispatch({ ...obj });
        }
      }
      return true
    }
  }))
  return obj.current;
};




export const useRefComputed = (initValue, func, updateType ) => {
  const [,dispatch] = useState(initValue);
  const obj = useRef(new Proxy({value:initValue}, {
    get: function(obj, prop) {
      if (obj[prop]) {
        return obj[prop];
      }
    },
    set: function(obj, prop, value) {
      if (obj[prop] !== value) {
        obj[prop] = value;
        func && func(obj[prop]);
        if(updateType?.deep){
          dispatch({ ...obj });
        }
      }
      return true
    }
  }))
  return obj.current;
};

