const parseTextAnnotations2BC =  (v) => {
	let line = {}
	let has = {}
	let desc = v?.[0]?.description;
	v.map((dd, ii)=>{
		if(ii>0){
			let indOf = getIndexOfList(desc, dd.description);
			indOf.map(nns=>{
				if(!line[dd.description] && !has[nns]){
					line[dd.description] = nns;
					has[nns] = dd.description;
				}
			})
		}
	})
	return line;
}


