const getTextfromIndex = (destxt) => {
		let iPos = getStore("lineDetectedText")?.[destxt];
		let image__text_detect = getStore("image__text_detect");
		let str = image__text_detect.fullTextAnnotation.text;
		let alpha = 1200;
		let fww = iPos - alpha;
		if(fww<0){
		  fww = 0;
		}
		let left2A =  str.slice(fww,iPos).split("\n");
		let left2 = left2A;
		if(left2A.length===1){
		  fww = iPos - (alpha *3);
		  if(fww<0){
			fww = 0;
		  }
		  left2A =  str.slice(fww,iPos).split("\n");
		}
		if(left2A.length>1){
		  left2 = left2A.pop();
		}
		let r2A =  str.slice(iPos,iPos+alpha).split("\n");
		let r2 = r2A[0];
		if(r2A.length===1){
		  r2A =  str.slice(iPos,iPos+(alpha*3)).split("\n");
		  r2 = r2A[0];
		}
		return left2+ r2;
}




